patch:
diff --git a/runtime/nvidia/op_attention.cuh b/runtime/nvidia/op_attention.cuh
index bad3a5d4..b47ff531 100644
--- a/runtime/nvidia/op_attention.cuh
+++ b/runtime/nvidia/op_attention.cuh
@@ -389,10 +389,32 @@ __device__ __forceinline__ void fa_ldmatrix_x2(unsigned (&r)[2], const void* sme
 #define PLOW_NV_FA_FP8PV 0
 #endif
 #if PLOW_NV_FA_FP8PV
-__device__ __forceinline__ void fa_ldmatrix_x2_trans_b8(unsigned (&r)[4], const void* smem) {
+__device__ __forceinline__ void fa_ldmatrix_x2_trans_b8(unsigned (&r)[4], const void* smem,
+                                                       unsigned row_stride) {
+#if defined(PLOW_NV_HOPPER)
+    const unsigned lane = threadIdx.x & 31;
+    unsigned v[4];
+    const unsigned s = (unsigned)__cvta_generic_to_shared(smem);
+    asm volatile("ldmatrix.sync.aligned.m8n8.x4.trans.shared.b16 {%0,%1,%2,%3}, [%4];\n"
+                 : "=r"(v[0]), "=r"(v[1]), "=r"(v[2]), "=r"(v[3]) : "r"(s));
+    const unsigned n = lane >> 2, q = lane & 3;
+#pragma unroll
+    for (unsigned matrix = 0; matrix < 2; ++matrix)
+#pragma unroll
+        for (unsigned half = 0; half < 2; ++half) {
+            const unsigned src = 4 * ((n + half * 8) >> 1) + 2 * (q & 1);
+            const unsigned a0 = __shfl_sync(0xffffffffu, v[matrix * 2], src);
+            const unsigned a1 = __shfl_sync(0xffffffffu, v[matrix * 2 + 1], src);
+            const unsigned b0 = __shfl_sync(0xffffffffu, v[matrix * 2], src + 1);
+            const unsigned b1 = __shfl_sync(0xffffffffu, v[matrix * 2 + 1], src + 1);
+            r[matrix * 2 + half] = __byte_perm((q & 2) ? a1 : a0, (q & 2) ? b1 : b0,
+                                              (n & 1) ? 0x7531 : 0x6420);
+        }
+#else
     unsigned s = (unsigned)__cvta_generic_to_shared(smem);
     asm volatile("ldmatrix.sync.aligned.m16n16.x2.trans.shared.b8 {%0,%1,%2,%3}, [%4];\n"
                  : "=r"(r[0]), "=r"(r[1]), "=r"(r[2]), "=r"(r[3]) : "r"(s));
+#endif
 }
 #endif
 /* kv row -> smem row for the V tile of the PX-8 arm (BKV=32). Bijection; see above. */
@@ -2698,6 +2720,9 @@ __device__ void d_flash_prefill_px8(float* __restrict__ Opart, float* __restrict

             /* Register softmax fused into the e4m3 P.V A fragment. */
             unsigned af_pv[4];
+#if defined(PLOW_NV_HOPPER)
+            unsigned af_pv_lo[4] = {};
+#endif
             {
                 float vmax = 0.0f;
 #pragma unroll
@@ -2754,6 +2779,14 @@ __device__ void d_flash_prefill_px8(float* __restrict__ Opart, float* __restrict
                     u[1] |= (unsigned)quant_fp8(p[1][b]) << (8 * b);
                     u[2] |= (unsigned)quant_fp8(p[0][4 + b]) << (8 * b);
                     u[3] |= (unsigned)quant_fp8(p[1][4 + b]) << (8 * b);
+#if defined(PLOW_NV_HOPPER)
+#pragma unroll
+                    for (int w = 0; w < 4; ++w) {
+                        const float value = p[w & 1][4 * (w >> 1) + b];
+                        const uint8_t hi = (u[w] >> (8 * b)) & 255;
+                        af_pv_lo[w] |= unsigned(quant_fp8((value - fp8_to_f32(hi)) * 32.0f)) << (8 * b);
+                    }
+#endif
                 }
                 af_pv[0] = u[0]; af_pv[1] = u[1]; af_pv[2] = u[2]; af_pv[3] = u[3];
                 /* The tile's P normaliser must NOT multiply the 64 mma outputs. Carry it in the
@@ -2778,10 +2811,24 @@ __device__ void d_flash_prefill_px8(float* __restrict__ Opart, float* __restrict
 #pragma unroll
             for (int nj = 0; nj < NJ_PV; nj += 2) {
                 unsigned rb[4];
-                fa_ldmatrix_x2_trans_b8(rb, &Vs8[lane * (HD + PAD8) + pv_wn * HDW + nj * 8]);
+                fa_ldmatrix_x2_trans_b8(rb, &Vs8[lane * (HD + PAD8) + pv_wn * HDW + nj * 8],
+                                       HD + PAD8);
                 unsigned b0[2] = {rb[0], rb[2]}, b1[2] = {rb[1], rb[3]};
+#if defined(PLOW_NV_HOPPER)
+#pragma unroll
+                for (int j = 0; j < 2; ++j) {
+                    const auto& b = j ? b1 : b0;
+                    float hi[4] = {}, lo[4] = {};
+                    fa_mma_fp8_k32(hi, af_pv, b, hi);
+                    fa_mma_fp8_k32(lo, af_pv_lo, b, lo);
+#pragma unroll
+                    for (int e = 0; e < 4; ++e)
+                        oacc[nj + j][e] += hi[e] + lo[e] * (1.0f / 32.0f);
+                }
+#else
                 fa_mma_fp8_k32(oacc[nj], af_pv, b0, oacc[nj]);
                 fa_mma_fp8_k32(oacc[nj + 1], af_pv, b1, oacc[nj + 1]);
+#endif
             }
             __syncthreads(); /* P.V done reading Vs8 before V[t+1] restages it */
         }
